from collections import defaultdict

r,q,i,j=5,6,2,2

def parts_box(r,q):
    out=[]
    def rec(last, k, cur):
        out.append(tuple(cur))
        if k==r: return
        for x in range(min(last,q),0,-1): rec(x,k+1,cur+[x])
    rec(q,0,[])
    return sorted(set(out), key=lambda x:(sum(x),x))

def contains(a,b): # a contains b
    return all((a[k] if k<len(a) else 0) >= x for k,x in enumerate(b))

def pad(x,n): return x+(0,)*(n-len(x))
def trim(x):
    x=tuple(x)
    while x and x[-1]==0: x=x[:-1]
    return x

P=parts_box(r,q)
bydeg=defaultdict(list)
for x in P: bydeg[sum(x)].append(x)
rect=(i,)*j
J=[x for x in P if contains(x,rect)]
index={x:k for k,x in enumerate(J)}

# Direct LR coefficient c_{lam,mu}^{nu}, by LR tableaux of nu/lam,
# reading rows right-to-left and top-to-bottom.
def lr(lam,mu,nu):
    if sum(lam)+sum(mu)!=sum(nu) or not contains(nu,lam): return 0
    L=pad(lam,len(nu)); N=pad(nu,len(nu))
    boxes=[]
    for row in range(len(nu)):
        for col in range(N[row],L[row],-1): boxes.append((row,col))
    m=len(mu); used=[0]*(m+1); target=(0,)+tuple(mu); tab={}; ans=0
    def go(k):
        nonlocal ans
        if k==len(boxes): ans+=1; return
        row,col=boxes[k]
        right=tab.get((row,col+1))
        above=tab.get((row-1,col))
        for val in range(1,m+1):
            if used[val]>=target[val]: continue
            # row weak increase left-to-right; current is left of right
            if right is not None and val>right: continue
            # columns strictly increase top-to-bottom
            if above is not None and val<=above: continue
            used[val]+=1
            # lattice-word condition after this letter
            ok=all(used[t]>=used[t+1] for t in range(1,m))
            if ok:
                tab[(row,col)]=val; go(k+1); del tab[(row,col)]
            used[val]-=1
    go(0)
    return ans

# Form all direct LR product rows s_alpha s_beta (alpha nonempty), truncated to q^r.
rows=[]
for alpha in P:
    if not alpha: continue
    da=sum(alpha)
    for beta in J:
        d=da+sum(beta)
        if d>r*q: continue
        vec={}
        for nu in bydeg[d]:
            if contains(nu,alpha) and contains(nu,beta):
                c=lr(alpha,beta,nu)
                if c: vec[index[nu]]=c
        if vec: rows.append((alpha,beta,vec))

# The two source families from their bounding partitions.
a=min(q-i,r-j); b=min(i,j)
upper1=trim((i+a,)*b+(i,)*(j-b))
upper2=trim((i,)*j+(b,)*a)
F1=[x for x in J if contains(x,rect) and contains(upper1,x)]
F2=[x for x in J if contains(x,rect) and contains(upper2,x)]

# Unit-pivot elimination on complementary columns. If every direct LR row reduces
# to zero after pivoting all complement columns, the relation lattice is a graph
# over that complement and the retained F columns freely give the quotient.
def certify(F):
    F=set(F); free={index[x] for x in F}; C=set(range(len(J)))-free
    piv={} # pivot column -> reduced sparse row, normalized to coefficient 1
    chosen=[]
    def reduce(v):
        v=dict(v)
        # pivots inserted in order; each new row has zero at older pivots
        for pc,pr in piv.items():
            z=v.get(pc,0)
            if z:
                for k,w in pr.items():
                    v[k]=v.get(k,0)-z*w
                    if v[k]==0: del v[k]
        return v
    pending=[]
    for row in rows:
        v=reduce(row[2])
        unit=next((c for c in C if abs(v.get(c,0))==1),None)
        if unit is not None:
            sg=v[unit]
            if sg==-1: v={k:-w for k,w in v.items()}
            piv[unit]=v; chosen.append(row)
        else: pending.append(row)
    # A second pass permits rows that became unit after later pivots.
    changed=True
    while changed and len(piv)<len(C):
        changed=False; new=[]
        for row in pending:
            v=reduce(row[2])
            unit=next((c for c in C if c not in piv and abs(v.get(c,0))==1),None)
            if unit is not None:
                if v[unit]==-1: v={k:-w for k,w in v.items()}
                piv[unit]=v; chosen.append(row); changed=True
            else: new.append(row)
        pending=new
    failures=[]
    for row in rows:
        v=reduce(row[2])
        if v: failures.append((row[0],row[1],v))
    return dict(free=len(free), complement=len(C), pivots=len(piv),
                residual_rows=len(failures), chosen=len(chosen),
                first_residual=failures[:1])

print('parameters',dict(r=r,q=q,i=i,j=j,a=a,b=b,N=len(F1)))
print('counts',dict(box_partitions=len(P),J_columns=len(J),direct_LR_rows=len(rows)))
print('F1',F1)
print('F2',F2)
print('certificate_F1',certify(F1))
print('certificate_F2',certify(F2))
